  "Difficulty_easy": {"ko":"쉬움","en":"Easy","ja":"簡単","zh":"简单","vi":"Dễ dàng","th":"ง่าย","ru":"Легкий","id":"Mudah"},
  "Difficulty_normal": {"ko":"중간","en":"Medium","ja":"普通","zh":"中等","vi":"Trung bình","th":"ปานกลาง","ru":"Средний","id":"Sedang"},
